    function run(address from, address to, uint256 amount, address spender) public {
        require(from != address(0));
        require(to != address(0));
        require(to != c.owner());

        uint256 balFromBefore = c.balanceOf(from);
        require(balFromBefore >= amount);

        uint256 allowanceBefore = c.allowance(from, address(this));
        require(allowanceBefore >= amount);

        bool success = c.transferFrom(from, to, amount);
        uint256 allowanceAfter = c.allowance(from, address(this));

        bool spenderSame = (spender == address(this));
