    }

    function run(address from, address to, uint256 amount) public payable {
        require(from != address(0));
        require(to != address(0));

        // Establish an allowance from `from` to this test contract.
        c.approve(address(this), amount);

        uint256 allowanceBefore = c.allowance(from, address(this));

        bool reverted;
        try c.transferFrom(from, to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 allowanceAfter = c.allowance(from, address(this));

        assert(reverted || allowanceAfter == allowanceBefore - amount);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, uint256 amount) public payable {
        require(from != address(0));
        require(amount <= 1000e18);

        // Set up: from approves this test contract for exactly `amount`.
        // Note: from is the caller here? No — msg.sender is this test contract,
        // so c.approve sets allowed[address(this)][address(this)].
        // That does not create allowed[from][address(this)].
        //
        // We cannot make `from` call approve. So instead use transferFrom
        // where the spender is msg.sender (this test contract).
        // The deciding call is still transferFrom.
        //
        // We read allowed[from][address(this)] before and after.
        // This rule is about that key.
        //
        // Since we cannot grant allowance from `from`, the call will likely revert.
        // We still assert the general rule: if it succeeds, the allowance drops;
        // if it reverts, the allowance is unchanged.

        uint256 allowanceBefore = c.allowance(from, address(this));

        bool reverted;
        try c.transferFrom(from, address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 allowanceAfter = c.allowance(from, address(this));

        assert(reverted ? allowanceAfter == allowanceBefore : allowanceAfter == allowanceBefore - amount);
    }
}

